// 플랫폼이 보내는 계약 (app/notion_mapping/service.py verify_mapping):
//   { "action": "lookup_user", "email": "someone@goodmit.co.kr" }
// 사람 목록 화면을 위한 확장:
//   { "action": "list_users" }
//
// 이메일은 여기서 정규화한다. Notion이 돌려주는 person.email과 대소문자만 달라도
// 매칭이 실패하는데, 그러면 화면에는 '일치하는 Notion 사용자가 없습니다'로만 보여서
// 원인을 알 수 없다.
const body = $input.first().json.body || $input.first().json || {};
const action = String(body.action || 'lookup_user').trim();
const email = String(body.email || '').trim().toLowerCase();

if (action !== 'lookup_user' && action !== 'list_users') {
  return [{ json: { _error: `지원하지 않는 action입니다: ${action}` } }];
}
if (action === 'lookup_user' && !email) {
  return [{ json: { _error: 'lookup_user에는 email이 필요합니다.' } }];
}
return [{ json: { action, email } }];

// 조회 결과를 아이템 1개로 접는다. 이게 없으면 다음 조회 노드가 아이템마다 한 번씩
// 실행된다 — 작업 1026건이면 프로젝트 DB를 1026번 스캔한다(실제로 겪었다).
// 채팅 워크플로의 '작업 묶기'와 같은 패턴이다.
return [{ json: { tickets: $input.all().map((i) => i.json).filter((i) => i?.id) } }];

// 매핑할 사람은 워크스페이스 멤버 목록(/v1/users)이 아니라 **작업 데이터의 담당자**다.
// /v1/users는 이 통합에 2명만 노출한다(실측: checked=2). 우리가 매핑해야 하는 사람들은
// 티켓의 '티켓 담당자'와 프로젝트의 '담당자 정/부'에 들어 있고, 각 항목이
// {id, name, person:{email}} — 진짜 Notion user id다. 러너도 같은 우물을 쓴다
// (assistant.py build_directory / people_value).

const req = $('요청 해석').first().json;
if (req._error) {
  return [{ json: { error: req._error, matches: [] } }];
}

const bundle = $input.first().json || {};
const tickets = Array.isArray(bundle.tickets) ? bundle.tickets : null;
const projects = Array.isArray(bundle.projects) ? bundle.projects : null;
// 조회가 실패했는데 빈 목록을 '사람이 없다'로 답하면 사용자는 그 사람이 Notion에 없다고 믿는다.
if (tickets === null && projects === null) {
  return [{ json: { error: 'Notion 작업 데이터를 읽지 못했습니다.', matches: [] } }];
}

const found = new Map();
function collect(pages) {
  for (const page of (pages || [])) {
    const props = (page && page.properties) || {};
    for (const key of Object.keys(props)) {
      const prop = props[key] || {};
      let list = null;
      if (Array.isArray(prop.people)) list = prop.people;
      else if (prop.type === 'created_by' && prop.created_by) list = [prop.created_by];
      if (!list) continue;
      for (const u of list) {
        if (!u || !u.id) continue;
        if (u.type && u.type !== 'person') continue;   // 봇은 담당자가 될 수 없다
        const email = (u.person && u.person.email) ? String(u.person.email).trim().toLowerCase() : null;
        const prev = found.get(u.id) || { notion_email: null, name: null, seen: 0, props: {} };
        prev.props[key] = true;
        // 같은 사람이 여러 페이지에 나오는데 어떤 페이지는 email이 비어 온다. 한 번이라도
        // 채워진 값을 남긴다 — 마지막 페이지가 비었다는 이유로 이메일을 잃으면 매핑이 실패한다.
        found.set(u.id, {
          notion_user_id: u.id,
          notion_email: email || prev.notion_email,
          name: u.name || prev.name,
          seen: prev.seen + 1,
          props: prev.props,
        });
      }
    }
  }
}
collect(tickets);
collect(projects);

const people = Array.from(found.values())
  .map((p) => ({ notion_user_id: p.notion_user_id, notion_email: p.notion_email,
                 name: p.name, seen: p.seen, sources: Object.keys(p.props) }))
  .sort((a, b) => b.seen - a.seen);

if (req.action === 'list_users') {
  return [{ json: { users: people, total: people.length, has_more: false } }];
}
const matches = people.filter((p) => p.notion_email && p.notion_email === req.email);
return [{ json: { matches, checked: people.length, has_more: false } }];
